<script>
const apiBase='../api/index.php',el=id=>document.getElementById(id);
function showStatus(text,error){const box=el('smtpStatus');box.textContent=text;box.className='smtp-status show '+(error?'error':'ok')}
async function request(path,options={}){const response=await fetch(apiBase+path,{headers:{'Content-Type':'application/json'},...options}),data=await response.json().catch(()=>({error:'Respuesta inválida.'}));if(!response.ok||data.error)throw new Error(data.error||'No se pudo completar la operación.');return data}
function values(){return {smtp_host:el('smtpHost').value.trim(),smtp_port:el('smtpPort').value.trim(),smtp_security:el('smtpSecurity').value,smtp_user:el('smtpUser').value.trim(),smtp_password:el('smtpPassword').value,smtp_from_email:el('smtpFrom').value.trim(),smtp_from_name:el('smtpName').value.trim()}}
async function saveConfig(silent){const data=values();if(!data.smtp_host||!data.smtp_user||!data.smtp_from_email)throw new Error('Complete servidor, usuario y remitente.');await request('/correo/configuracion',{method:'POST',body:JSON.stringify(data)});el('smtpPassword').value='';if(!silent)showStatus('Configuración guardada correctamente.',false)}
async function testConfig(){try{await saveConfig(true);await request('/correo/probar',{method:'POST',body:JSON.stringify({email:el('smtpFrom').value.trim()})});showStatus('Correo de prueba enviado correctamente.',false)}catch(error){showStatus(error.message,true)}}
document.addEventListener('DOMContentLoaded',async()=>{try{const c=await request('/correo/configuracion');el('smtpHost').value=c.smtp_host||'';el('smtpPort').value=c.smtp_port||'587';el('smtpSecurity').value=c.smtp_security||'tls';el('smtpUser').value=c.smtp_user||'';el('smtpFrom').value=c.smtp_from_email||'';el('smtpName').value=c.smtp_from_name||'Neuro App';el('smtpPassword').placeholder=c.password_configured?'Clave guardada · deje vacío para conservarla':'Ingrese la clave de aplicación'}catch(error){showStatus(error.message,true)}});
</script>
